 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    # The row containing the horizontal pair is the spine; the other markers
    # project vertically to it.
    spine = max(by_row, key=lambda r: (len(by_row[r]), -r))
    spine_cols = by_row[spine]
    for c in range(min(spine_cols), max(spine_cols) + 1):
        if out[spine][c] == 0:
            out[spine][c] = 3
    for r, c in points:
        if r == spine:
            continue
        for rr in range(min(r, spine), max(r, spine) + 1):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
